// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ImageStyle) predicate.ImageStyle {
	return predicate.ImageStyle(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ImageStyle) predicate.ImageStyle {
	return predicate.ImageStyle(sql.NotPredicates(p))
}
